  rec:{rows:[["Tablero","88"],["Plataforma de datos · una copia","88"],["Sistema de estudiantes · el registro","88"]],ask:"¿qué registro, y qué palabra?"},
  gap:{note:"todas las pruebas pasaron",ask:"¿qué cuenta cada cifra?"},
